// server/app.ts
var app = express();
app.use(compression({ threshold: 512, level: 6 }));
app.use(express.json({ limit: "10mb" }));
app.use((req, res, next) => {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Access-Control-Allow-Methods", "GET, POST, PATCH, DELETE, OPTIONS");
  res.setHeader("Access-Control-Allow-Headers", "Content-Type, Authorization");
  if (req.method === "OPTIONS") {
    return res.sendStatus(200);
  }
  next();
});
var nseUnderlyingsJson = JSON.stringify(angelUnderlyings_default);
var nseInstrumentsJson = JSON.stringify(angelInstrumentsMap_default);
var bseUnderlyingsJson = JSON.stringify(bseUnderlyings_default);
var bseInstrumentsJson = JSON.stringify(bseInstrumentsMap_default);
var bseCashJson = JSON.stringify(bseCashUniverse_default);
var apiRouter = express.Router();
apiRouter.get("/health", (_req, res) => {
  res.json({
    status: "ok",
    timestamp: Date.now(),
    service: "Ratio Spread API",
    universeLoaded: {
      nse: angelUnderlyings_default.length,
      bse: bseUnderlyings_default.length,
      bseCash: bseCashUniverse_default.length
    }
  });
});
var sendStaticUniverse = (res, jsonStr) => {
  res.setHeader("Content-Type", "application/json");
  res.setHeader("Cache-Control", "public, max-age=86400, immutable");
  res.send(jsonStr);
};
apiRouter.get("/universe/nse-underlyings", (_req, res) => {
  sendStaticUniverse(res, nseUnderlyingsJson);
});
apiRouter.get("/universe/nse-instruments", (_req, res) => {
  sendStaticUniverse(res, nseInstrumentsJson);
});
apiRouter.get("/universe/bse-underlyings", (_req, res) => {
  sendStaticUniverse(res, bseUnderlyingsJson);
});
apiRouter.get("/universe/bse-instruments", (_req, res) => {
  sendStaticUniverse(res, bseInstrumentsJson);
});
apiRouter.get("/universe/bse-cash", (_req, res) => {
  sendStaticUniverse(res, bseCashJson);
});
apiRouter.use("/auth", authRouter);
apiRouter.use("/angel", marketRouter);
apiRouter.use("/user", strategyRouter);
apiRouter.use("/admin", adminRouter);
app.use("/api", apiRouter);
app.use((req, res, next) => {
  if (req.path.startsWith("/universe") || req.path.startsWith("/auth") || req.path.startsWith("/angel") || req.path.startsWith("/user") || req.path.startsWith("/admin") || req.path === "/health") {
    return apiRouter(req, res, next);
  }
  next();
});

// server.ts
process.on("uncaughtException", (err) => {
  console.error("[Server Supervisor] Trapped uncaughtException:", err?.stack || err);
});
process.on("unhandledRejection", (reason, promise) => {
  console.error("[Server Supervisor] Trapped unhandledRejection at:", promise, "reason:", reason);
});
async function startServer() {
  const PORT = Number(process.env.PORT) || 3e3;
  const distPath = path.join(process.cwd(), "dist");
  const distIndexExists = fs.existsSync(path.join(distPath, "index.html"));
  app.get("/api/health", (_req, res) => {
    const mem = process.memoryUsage();
    res.json({
      status: "HEALTHY",
      uptime: Math.round(process.uptime()),
      timestamp: Date.now(),
      memory: {
        rssMb: Math.round(mem.rss / 1024 / 1024),
        heapTotalMb: Math.round(mem.heapTotal / 1024 / 1024),
        heapUsedMb: Math.round(mem.heapUsed / 1024 / 1024)
      }
    });
  });
  if (process.env.NODE_ENV === "production" && distIndexExists) {
    console.log("[Server] Serving production compiled build from dist/");
    app.use("/assets", express2.static(path.join(distPath, "assets"), {
      maxAge: "1y",
      immutable: true,
      etag: true
    }));
    app.use(express2.static(distPath, { maxAge: "1h", etag: true }));
    app.get("*", (_req, res) => {
      res.setHeader("Cache-Control", "no-cache, no-store, must-revalidate");
      res.sendFile(path.join(distPath, "index.html"));
    });
  } else {
    console.log("[Server] Mounting Vite dev middleware for live compilation...");
    const vitePkg = "vite";
    const { createServer: createViteServer } = await import(vitePkg);
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa"
    });
    app.use(vite.middlewares);
  }
  app.use((err, _req, res, _next) => {
    console.error("[Server Express Error]:", err?.stack || err);
    if (!res.headersSent) {
      res.status(500).json({
        error: "Internal Server Error",
        message: err?.message || "Unexpected application error"
      });
    }
  });
  app.listen(PORT, "0.0.0.0", () => {
    console.log(`===========================================================`);
    console.log(`[Production Server] Ratio Spread Pro Terminal Running`);
    console.log(`[Status] ONLINE | Port: ${PORT} | Serving Build: ${distIndexExists}`);
    console.log(`[Supervisor] Crash recovery & instant compression active`);
    console.log(`===========================================================`);
  });
}
if (!process.env.VERCEL) {
  startServer().catch((err) => {
    console.error("[Server Startup Error]:", err);
    setTimeout(() => {
      console.log("[Server Supervisor] Attempting auto-restart after startup exception...");
      startServer().catch((e) => console.error("[Server Supervisor] Fatal restart failure:", e));
    }, 2e3);
  });
}
var server_default = app;
export {
  server_default as default
};
